package br.com.saraivamotos.repository;import java.util.*;import br.com.saraivamotos.domain.ContaReceber;import jakarta.persistence.LockModeType;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface ContaReceberRepository extends JpaRepository<ContaReceber,Long>{@EntityGraph(attributePaths={"recebimentos"})List<ContaReceber> findAllByOrderByVencimentoAscIdAsc();Optional<ContaReceber> findByVendaId(Long vendaId);@Lock(LockModeType.PESSIMISTIC_WRITE)@EntityGraph(attributePaths={"recebimentos"})@Query("SELECT DISTINCT c FROM ContaReceber c WHERE c.id=:id")Optional<ContaReceber> buscarParaAtualizar(@Param("id")Long id);@Query("SELECT COALESCE(SUM(c.saldoPendente),0) FROM ContaReceber c WHERE c.status IN (br.com.saraivamotos.domain.StatusContaReceber.ABERTA,br.com.saraivamotos.domain.StatusContaReceber.PARCIAL)")java.math.BigDecimal totalPendente();@Query("SELECT COALESCE(SUM(c.saldoPendente),0) FROM ContaReceber c WHERE c.status IN (br.com.saraivamotos.domain.StatusContaReceber.ABERTA,br.com.saraivamotos.domain.StatusContaReceber.PARCIAL) AND c.vencimento<CURRENT_DATE")java.math.BigDecimal totalVencido();}
